<script setup lang="ts">
import { computed, reactive, ref } from 'vue'
import { RouterLink } from 'vue-router'
import { LayoutDashboard, Package, Image, MousePointer2, GitBranch, ShoppingBag, Plus, Pencil, Trash2, X, Upload, Download, Printer, CheckCircle2, ArrowUpRight, Eye, ExternalLink, MapPinned, ChevronRight, CircleAlert, Ticket, Grid2X2, List, Search, Tags, Copy, Check } from 'lucide-vue-next'
import { products, type Product, type ProductVariant, money } from '../data/products'
import { analyticsEvents, orders, storefront, metricSummary, storageIssue, createProduct, deleteProduct, downloadOrdersCsv, resetDemoData, updateOrderStatus, updateProduct, coupons, createCoupon, deleteCoupon, type Coupon, type Order } from '../admin-store'

type Tab = 'Visão geral' | 'Produtos' | 'Capas' | 'Mapa de cliques' | 'Funil' | 'Pedidos' | 'Cupons'
const tabs: Array<{ label: Tab; icon: typeof LayoutDashboard }> = [
  { label: 'Visão geral', icon: LayoutDashboard }, { label: 'Produtos', icon: Package }, { label: 'Capas', icon: Image }, { label: 'Mapa de cliques', icon: MousePointer2 }, { label: 'Funil', icon: GitBranch }, { label: 'Pedidos', icon: ShoppingBag }, { label: 'Cupons', icon: Ticket },
]
const tab = ref<Tab>('Visão geral')
const editing = ref<number | null>(null)
const selectedOrderId = ref<string>('')
const uploadError = ref('')
const productView = ref<'grid' | 'list'>('grid')
const productSearch = ref('')
const productStatus = ref<'all' | 'active' | 'inactive'>('all')
const selectedProductIds = ref<number[]>([])
const couponDraft = reactive<Omit<Coupon, 'id' | 'used'>>({ code: '', type: 'percentage', value: 10, minimumOrder: 0, usageLimit: null, active: true })
const draft = reactive<Omit<Product, 'id'>>({ name: '', price: 0, category: 'Camisas', sizes: ['P', 'M', 'G', 'GG'], image: '/products/aegon-polo-on-model.png', images: ['/products/aegon-polo-on-model.png'], description: '', specs: [''], color: '#0045BA', colorName: 'Azul System Wake', badge: '', active: true, sku: '', stock: 0, tags: [], variants: [] })
const selectedOrder = computed(() => orders.find(order => order.id === selectedOrderId.value) || orders[0])
const heatPoints = computed(() => analyticsEvents.filter(event => event.name === 'product_click' && typeof event.x === 'number' && typeof event.y === 'number').slice(-35))
const funnel = computed(() => [
  { label: 'Passou o mouse', value: metricSummary.value.hovers, color: '#7CB9F2' },
  { label: 'Clicou no produto', value: metricSummary.value.clicks, color: '#0045BA' },
  { label: 'Adicionou à sacola', value: metricSummary.value.carts, color: '#FFC126' },
  { label: 'Iniciou checkout', value: metricSummary.value.checkouts, color: '#FF8100' },
  { label: 'Pedido concluído', value: metricSummary.value.sold, color: '#047857' },
])
const funnelMax = computed(() => Math.max(1, ...funnel.value.map(step => step.value)))
const filteredProducts = computed(() => {
  const query = productSearch.value.trim().toLocaleLowerCase('pt-BR')
  return products.filter(product => (productStatus.value === 'all' || (productStatus.value === 'active' ? product.active !== false : product.active === false)) && (!query || [product.name, product.sku, product.category, ...(product.tags || [])].filter(Boolean).join(' ').toLocaleLowerCase('pt-BR').includes(query)))
})
const allVisibleSelected = computed(() => !!filteredProducts.value.length && filteredProducts.value.every(product => selectedProductIds.value.includes(product.id)))
function resetDraft(product?: Product) {
  editing.value = product?.id ?? null
  Object.assign(draft, product ? { ...product, sizes: [...product.sizes], specs: [...product.specs], tags: [...(product.tags || [])], variants: (product.variants?.length ? product.variants : product.sizes.map((size, index) => ({ id: `${product.id}-${index}`, size, sku: `${product.sku || 'AEG'}-${size}`, stock: 0 }))).map(variant => ({ ...variant })), images: [...(product.images?.length ? product.images : [product.image])] } : { name: '', price: 0, category: 'Camisas', sizes: ['P', 'M', 'G', 'GG'], image: '/products/aegon-polo-on-model.png', images: ['/products/aegon-polo-on-model.png'], description: '', specs: [''], color: '#0045BA', colorName: 'Azul System Wake', badge: '', active: true, sku: '', stock: 0, tags: [], variants: [] })
  uploadError.value = ''
}
function saveProduct() {
  const variants = (draft.variants || []).filter(variant => variant.size.trim()).map(variant => ({ ...variant, size: variant.size.trim(), sku: variant.sku.trim(), stock: Math.max(0, Number(variant.stock) || 0) }))
  const product = { ...draft, name: draft.name.trim(), price: Number(draft.price), sku: draft.sku?.trim() || undefined, stock: Math.max(0, Number(draft.stock) || variants.reduce((total, variant) => total + variant.stock, 0)), tags: (draft.tags || []).map(tag => tag.trim()).filter(Boolean), sizes: (variants.length ? variants.map(variant => variant.size) : draft.sizes).filter(Boolean), variants, specs: draft.specs.filter(Boolean), images: draft.images?.filter(Boolean) || [], image: draft.images?.[0] || draft.image, description: draft.description.trim(), badge: draft.badge?.trim() || undefined }
  if (!product.name || !product.description || !product.sizes.length || product.price < 0) return
  if (editing.value) updateProduct(editing.value, product)
  else createProduct(product)
  editing.value = null
}
function removeProduct(product: Product) {
  if (window.confirm(`Remover “${product.name}” do catálogo? Esta ação só poderá ser desfeita ao restaurar os dados do navegador.`)) deleteProduct(product.id)
}
function updateFiles(event: Event) {
  const files = Array.from((event.target as HTMLInputElement).files || [])
  if (!files.length) return
  uploadError.value = ''
  if (files.some(file => !file.type.startsWith('image/') || file.size > 2_000_000)) { uploadError.value = 'Use imagens de até 2 MB em JPG, PNG, WebP ou SVG.'; return }
  Promise.all(files.map(file => new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onload = () => resolve(String(reader.result)); reader.onerror = reject; reader.readAsDataURL(file) }))).then(images => { draft.images = [...(draft.images || []), ...images]; draft.image = draft.images[0] || draft.image }).catch(() => { uploadError.value = 'Não foi possível ler a imagem selecionada.' })
}
function removeImage(index: number) { draft.images?.splice(index, 1); draft.image = draft.images?.[0] || '/products/aegon-polo-on-model.png' }
function printLabel() { window.print() }
function setSizes(value: string) {
  const sizes = value.split(',').map(size => size.trim()).filter(Boolean)
  const old = draft.variants || []
  draft.sizes = sizes
  draft.variants = sizes.map((size, index) => old.find(variant => variant.size === size) || ({ id: crypto.randomUUID?.() || `${Date.now()}-${index}`, size, sku: `${draft.sku || 'AEG'}-${size}`, stock: 0 }))
}
function addVariant() { draft.variants = [...(draft.variants || []), { id: crypto.randomUUID?.() || `${Date.now()}-${draft.variants?.length || 0}`, size: '', sku: draft.sku || '', stock: 0 }] }
function removeVariant(index: number) { draft.variants?.splice(index, 1); draft.sizes = (draft.variants || []).map(variant => variant.size).filter(Boolean) }
function syncVariants() { draft.sizes = (draft.variants || []).map(variant => variant.size.trim()).filter(Boolean) }
function toggleVisibleProducts() { selectedProductIds.value = allVisibleSelected.value ? selectedProductIds.value.filter(id => !filteredProducts.value.some(product => product.id === id)) : [...new Set([...selectedProductIds.value, ...filteredProducts.value.map(product => product.id)])] }
function setSelectedProductsActive(active: boolean) { products.filter(product => selectedProductIds.value.includes(product.id)).forEach(product => { product.active = active }); selectedProductIds.value = [] }
function saveCoupon() { if (!couponDraft.code.trim() || (couponDraft.type !== 'shipping' && Number(couponDraft.value) <= 0)) return; createCoupon({ ...couponDraft, code: couponDraft.code.trim(), value: Number(couponDraft.value) || 0, minimumOrder: Number(couponDraft.minimumOrder) || 0, usageLimit: couponDraft.usageLimit ? Number(couponDraft.usageLimit) : null }); Object.assign(couponDraft, { code: '', type: 'percentage', value: 10, minimumOrder: 0, usageLimit: null, active: true }) }
function copyCoupon(code: string) { navigator.clipboard?.writeText(code) }
</script>

<template>
  <div class="admin-shell">
    <aside class="admin-sidebar">
      <RouterLink to="/" class="admin-logo" aria-label="Voltar para a loja"><img src="/brand/assets/Logos/aegon-logo-escuro.svg" alt="aegon" /><span>admin</span></RouterLink>
      <nav aria-label="Navegação administrativa"><button v-for="item in tabs" :key="item.label" :class="{ selected: tab === item.label }" @click="tab = item.label"><component :is="item.icon" :size="18" />{{ item.label }}</button></nav>
      <div class="admin-sidebar-bottom"><RouterLink to="/" target="_blank"><ExternalLink :size="16" />Ver loja</RouterLink><span>Modo local · v0.1</span></div>
    </aside>
    <main class="admin-main">
      <header class="admin-topbar"><div><span class="eyebrow">AEGON STORE / OPERAÇÃO</span><h1>{{ tab }}</h1></div><div class="admin-topbar-actions"><span class="admin-live"><i></i> Dados deste navegador</span><RouterLink to="/" class="button button-outline">Ver loja <ArrowUpRight :size="16" /></RouterLink></div></header>
      <p v-if="storageIssue" class="admin-alert"><CircleAlert :size="18" />{{ storageIssue }}</p>

      <section v-if="tab === 'Visão geral'" class="admin-view">
        <div class="admin-welcome"><div><span class="eyebrow">PAINEL DE OPERAÇÃO</span><h2>Uma visão clara do que está <span>on</span>.</h2><p>Leituras de navegação, pedidos de demonstração e atalhos da sua loja.</p></div><button class="button button-primary" @click="tab = 'Produtos'; resetDraft()"><Plus :size="17" />Novo produto</button></div>
        <div class="metric-grid"><article><span>Pedidos concluídos</span><strong>{{ metricSummary.sold }}</strong><small>nesta instalação</small></article><article><span>Receita simulada</span><strong>{{ money(metricSummary.revenue) }}</strong><small>sem processamento financeiro</small></article><article><span>Adições à sacola</span><strong>{{ metricSummary.carts }}</strong><small>{{ metricSummary.clicks ? `${Math.round(metricSummary.carts / metricSummary.clicks * 100)}% dos cliques` : 'aguardando navegação' }}</small></article><article><span>Conversão</span><strong>{{ metricSummary.conversion.toFixed(1).replace('.', ',') }}%</strong><small>pedido / clique no produto</small></article></div>
        <div class="admin-split"><section class="admin-panel"><div class="admin-panel-title"><div><span class="eyebrow">PRÓXIMA AÇÃO</span><h3>Pedidos recentes</h3></div><button class="text-link" @click="tab = 'Pedidos'">Ver todos <ChevronRight :size="16" /></button></div><div v-if="orders.length" class="admin-order-list"><button v-for="order in orders.slice(0, 4)" :key="order.id" @click="tab = 'Pedidos'; selectedOrderId = order.id"><span><strong>{{ order.id }}</strong><small>{{ order.customer.name }} · {{ new Date(order.createdAt).toLocaleDateString('pt-BR') }}</small></span><span><em :class="`status-${order.status.toLowerCase()}`">{{ order.status }}</em><strong>{{ money(order.total) }}</strong></span></button></div><div v-else class="admin-empty"><ShoppingBag :size="28" /><p>Ainda não há pedidos por aqui.</p><small>Conclua a simulação de checkout na loja e ele aparecerá aqui.</small></div></section>
          <section class="admin-panel"><div class="admin-panel-title"><div><span class="eyebrow">FILA DA LOJA</span><h3>Funil agora</h3></div><button class="text-link" @click="tab = 'Funil'">Abrir funil <ChevronRight :size="16" /></button></div><div class="mini-funnel"><div v-for="step in funnel" :key="step.label"><span>{{ step.label }}</span><b><i :style="{ width: `${step.value / funnelMax * 100}%`, background: step.color }"></i></b><strong>{{ step.value }}</strong></div></div></section></div>
        <section class="admin-panel quick-actions"><div><span class="eyebrow">ATALHOS</span><h3>O que você quer ajustar?</h3></div><button @click="tab = 'Capas'"><Image :size="22" />Capas da loja <ArrowUpRight :size="16" /></button><button @click="tab = 'Mapa de cliques'"><MapPinned :size="22" />Mapa de cliques <ArrowUpRight :size="16" /></button><button @click="tab = 'Produtos'; resetDraft()"><Package :size="22" />Criar produto <ArrowUpRight :size="16" /></button></section>
      </section>

      <section v-else-if="tab === 'Produtos'" class="admin-view">
        <div class="admin-section-head"><div><p>Crie, edite, publique ou retire itens do catálogo. As alterações aparecem na loja imediatamente neste navegador.</p></div><button class="button button-primary" @click="resetDraft()"><Plus :size="17" />Novo produto</button></div>
        <div class="admin-catalog-toolbar"><div class="admin-search"><Search :size="16" /><input v-model="productSearch" placeholder="Buscar por produto, SKU ou tag" /></div><select v-model="productStatus" aria-label="Filtrar status"><option value="all">Todos os produtos</option><option value="active">Publicados</option><option value="inactive">Ocultos</option></select><div class="admin-view-toggle"><button :class="{ active: productView === 'grid' }" title="Visualização em grade" @click="productView = 'grid'"><Grid2X2 :size="17" /></button><button :class="{ active: productView === 'list' }" title="Visualização em lista" @click="productView = 'list'"><List :size="17" /></button></div></div>
        <div v-if="selectedProductIds.length" class="admin-bulk-bar"><strong>{{ selectedProductIds.length }} selecionado{{ selectedProductIds.length > 1 ? 's' : '' }}</strong><button @click="setSelectedProductsActive(true)">Publicar</button><button @click="setSelectedProductsActive(false)">Ocultar</button><button class="text-link" @click="selectedProductIds = []">Limpar seleção</button></div>
        <div class="admin-catalog"><section class="admin-panel product-manager"><div class="admin-panel-title"><label class="catalog-check"><input :checked="allVisibleSelected" type="checkbox" @change="toggleVisibleProducts" /><span></span></label><h3>Catálogo <span>{{ filteredProducts.length }} de {{ products.length }} itens</span></h3></div><div v-if="productView === 'grid'" class="admin-product-grid"><article v-for="product in filteredProducts" :key="product.id" :class="{ checked: selectedProductIds.includes(product.id) }"><label class="product-select"><input v-model="selectedProductIds" type="checkbox" :value="product.id" /><span></span></label><img :src="product.image" :alt="product.name" /><div class="product-grid-copy"><span class="admin-status" :class="{ muted: product.active === false }">{{ product.active === false ? 'Oculto' : 'Publicado' }}</span><strong>{{ product.name }}</strong><small>{{ product.sku || 'Sem SKU' }} · Estoque {{ product.stock ?? 0 }}</small><div class="admin-tag-row"><i v-for="tag in (product.tags || []).slice(0, 2)" :key="tag">{{ tag }}</i></div><b>{{ money(product.price) }}</b></div><div class="product-card-actions"><button class="icon-button" :aria-label="`Editar ${product.name}`" @click="resetDraft(product)"><Pencil :size="16" /></button><button class="icon-button danger" :aria-label="`Remover ${product.name}`" @click="removeProduct(product)"><Trash2 :size="16" /></button></div></article><p v-if="!filteredProducts.length" class="catalog-no-results">Nenhum produto encontrado com estes filtros.</p></div><div v-else class="admin-product-rows"><article v-for="product in filteredProducts" :key="product.id"><label class="product-select"><input v-model="selectedProductIds" type="checkbox" :value="product.id" /><span></span></label><img :src="product.image" :alt="product.name" /><div><strong>{{ product.name }}</strong><small>{{ product.sku || 'Sem SKU' }} · {{ product.category }} · {{ money(product.price) }} · Estoque {{ product.stock ?? 0 }}</small><div class="admin-tag-row"><i v-for="tag in (product.tags || []).slice(0, 2)" :key="tag">{{ tag }}</i></div></div><button class="icon-button" :aria-label="`Editar ${product.name}`" @click="resetDraft(product)"><Pencil :size="17" /></button><button class="icon-button danger" :aria-label="`Remover ${product.name}`" @click="removeProduct(product)"><Trash2 :size="17" /></button></article><p v-if="!filteredProducts.length" class="catalog-no-results">Nenhum produto encontrado com estes filtros.</p></div></section>
          <form class="admin-panel product-editor" @submit.prevent="saveProduct">
            <div class="admin-panel-title"><div><span class="eyebrow">{{ editing ? 'EDITAR PRODUTO' : 'NOVO PRODUTO' }}</span><h3>{{ editing ? 'Ajuste o essencial.' : 'Crie um essencial.' }}</h3></div><button v-if="editing" type="button" class="icon-button" aria-label="Fechar edição" @click="editing = null"><X :size="18" /></button></div>
            <div class="admin-form-grid">
              <label class="admin-form-span">Nome<input v-model.trim="draft.name" required maxlength="100" placeholder="Ex.: Polo Aegon System Wake" /></label>
              <label>Preço (R$)<input v-model.number="draft.price" required min="0" step="0.01" type="number" /></label><label>Categoria<select v-model="draft.category"><option>Camisas</option><option>Garrafas</option><option>Cadernos</option><option>Combos</option></select></label>
              <label>SKU principal<input v-model.trim="draft.sku" placeholder="AEG-POLO-001" /></label><label>Estoque total<input v-model.number="draft.stock" min="0" type="number" /></label>
              <label class="admin-form-span">Tags <small>Separe por vírgula</small><input :value="(draft.tags || []).join(', ')" @input="draft.tags = ($event.target as HTMLInputElement).value.split(',').map(tag => tag.trim())" placeholder="Novo, Uniforme, Coleção 01" /></label>
              <label>Cor<input v-model.trim="draft.colorName" required placeholder="Azul System Wake" /></label><label>Hex<input v-model="draft.color" required pattern="#[0-9a-fA-F]{6}" placeholder="#0045BA" /></label>
              <label class="admin-form-span">Tamanhos / opções <small>Ao editar, as variações abaixo acompanham.</small><input :value="draft.sizes.join(', ')" @input="setSizes(($event.target as HTMLInputElement).value)" placeholder="P, M, G, GG" /></label>
              <div class="admin-form-span variant-editor"><div><span><Tags :size="15" />Variações de tamanho</span><button type="button" class="text-link" @click="addVariant"><Plus :size="14" />Adicionar variação</button></div><section v-for="(variant, index) in draft.variants" :key="variant.id" class="variant-row"><input v-model.trim="variant.size" required placeholder="Tamanho" @change="syncVariants" /><input v-model.trim="variant.sku" placeholder="SKU da variação" /><input v-model.number="variant.stock" min="0" type="number" placeholder="Estoque" /><button type="button" class="icon-button danger" :aria-label="`Remover variação ${index + 1}`" @click="removeVariant(index)"><Trash2 :size="15" /></button></section><small v-if="!draft.variants?.length">Adicione tamanhos para controlar SKU e estoque por variação.</small></div>
              <label class="admin-form-span">Descrição<textarea v-model.trim="draft.description" required rows="3" placeholder="Conte a história deste essencial."></textarea></label><label class="admin-form-span">Detalhes <small>Um por linha</small><textarea :value="draft.specs.join('\n')" rows="4" @input="draft.specs = ($event.target as HTMLTextAreaElement).value.split('\n')" placeholder="Material\nAcabamento\nCuidados"></textarea></label><label class="admin-form-span">Selo opcional<input v-model.trim="draft.badge" placeholder="Ex.: Novo por aqui" /></label><label class="admin-check"><input v-model="draft.active" type="checkbox" />Publicar agora</label>
            </div>
            <div class="admin-media"><span>Fotos do produto</span><div class="admin-image-list"><div v-for="(image, index) in draft.images" :key="image" class="admin-image-thumb"><img :src="image" alt="Prévia" /><button type="button" :aria-label="`Remover foto ${index + 1}`" @click="removeImage(index)"><X :size="14" /></button></div><label class="admin-upload"><Upload :size="20" /><span>Adicionar fotos</span><input accept="image/png,image/jpeg,image/webp,image/svg+xml" multiple type="file" @change="updateFiles" /></label></div><small v-if="uploadError" class="field-error">{{ uploadError }}</small><small>JPG, PNG, WebP ou SVG, até 2 MB por foto. A primeira será a capa.</small></div><button class="button button-primary full-width" type="submit"><CheckCircle2 :size="17" />{{ editing ? 'Salvar alterações' : 'Criar produto' }}</button>
          </form></div>
      </section>

      <section v-else-if="tab === 'Capas'" class="admin-view">
        <div class="admin-section-head"><p>Edite a mensagem e a imagem da capa principal. A atualização aparece no topo da loja no mesmo instante.</p><RouterLink to="/" target="_blank" class="button button-outline">Abrir capa <Eye :size="16" /></RouterLink></div><div class="admin-covers"><form class="admin-panel cover-form"><div class="admin-panel-title"><div><span class="eyebrow">CAPA PRINCIPAL</span><h3>A primeira impressão.</h3></div></div><label>Chamada superior<input v-model="storefront.eyebrow" maxlength="70" /></label><label>Título, primeira linha<input v-model="storefront.headline" maxlength="40" /></label><label>Texto em destaque<input v-model="storefront.highlight" maxlength="40" /></label><label>Texto de apoio<textarea v-model="storefront.subtitle" rows="3" maxlength="150"></textarea></label><label>Texto do botão<input v-model="storefront.cta" maxlength="60" /></label><label>Imagem da capa <small>URL local ou imagem enviada no produto</small><input v-model="storefront.heroImage" placeholder="/editorial/aegon-flatlay.png" /></label></form><section class="admin-panel cover-preview"><span class="eyebrow">PRÉVIA AO VIVO</span><div class="cover-card"><div><small>{{ storefront.eyebrow }}</small><h2>{{ storefront.headline }}<br /><b>{{ storefront.highlight }}</b></h2><p>{{ storefront.subtitle }}</p><button>{{ storefront.cta }}</button></div><img :src="storefront.heroImage" alt="Prévia da capa" /></div><p class="cover-tip">Use uma imagem hospedada em <code>/public</code> ou uma foto escolhida na edição de produto.</p></section></div>
      </section>

      <section v-else-if="tab === 'Mapa de cliques'" class="admin-view">
        <div class="admin-section-head"><div><p>Mostra os cliques registrados nas páginas de produto da loja aberta neste navegador. Passe o mouse e clique em produtos para gerar leituras reais de teste.</p></div><button class="button button-outline" @click="resetDemoData"><Trash2 :size="16" />Limpar dados locais</button></div><div class="heatmap-layout"><section class="admin-panel heatmap-panel"><div class="admin-panel-title"><div><span class="eyebrow">CLIQUE EM PRODUTOS</span><h3>Mapa de atenção</h3></div><strong>{{ heatPoints.length }} pontos</strong></div><div class="heatmap-canvas" aria-label="Mapa de cliques da loja"><div class="heatmap-header">aegon <span>store</span></div><div class="heatmap-mock-hero"><span>MENOS DO<br />MESMO.</span><b>MAIS VOCÊ.</b></div><div class="heatmap-products"><i v-for="n in 4" :key="n"></i></div><span v-for="point in heatPoints" :key="point.id" class="heat-point" :style="{ left: `${point.x}%`, top: `${point.y}%` }"></span><div v-if="!heatPoints.length" class="heatmap-empty"><MousePointer2 :size="30" />Nenhum clique registrado ainda.</div></div></section><section class="admin-panel event-feed"><div class="admin-panel-title"><div><span class="eyebrow">EVENTOS RECENTES</span><h3>O que as pessoas fizeram</h3></div></div><div v-if="analyticsEvents.length"><article v-for="event in analyticsEvents.slice().reverse().slice(0, 10)" :key="event.id"><span class="event-icon"><MousePointer2 :size="14" /></span><div><strong>{{ event.name === 'product_hover' ? 'Passou o mouse' : event.name === 'product_click' ? 'Clicou no produto' : event.name === 'add_to_cart' ? 'Adicionou à sacola' : event.name === 'checkout_started' ? 'Iniciou checkout' : 'Concluiu pedido' }}</strong><small>{{ products.find(product => product.id === event.productId)?.name || event.path }} · {{ new Date(event.at).toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }) }}</small></div></article></div><div v-else class="admin-empty"><MapPinned :size="28" /><p>O mapa começa a aprender quando a loja recebe interação.</p></div></section></div>
      </section>

      <section v-else-if="tab === 'Funil'" class="admin-view">
        <div class="admin-section-head"><p>Do primeiro interesse até a conclusão do pedido. Cada etapa é registrada pela navegação nesta instalação.</p></div><section class="admin-panel funnel-panel"><div v-for="(step, index) in funnel" :key="step.label" class="funnel-step"><div><span>{{ String(index + 1).padStart(2, '0') }}</span><strong>{{ step.label }}</strong></div><div class="funnel-bar"><i :style="{ width: `${step.value / funnelMax * 100}%`, background: step.color }"></i></div><b>{{ step.value }}</b><small v-if="index">{{ funnel[index - 1].value ? `${Math.round(step.value / funnel[index - 1].value * 100)}% avançaram` : '—' }}</small></div></section><div class="admin-split"><section class="admin-panel"><span class="eyebrow">LEITURA RÁPIDA</span><h3>{{ metricSummary.sold ? 'Há pedidos no fluxo.' : 'Ainda sem conversões.' }}</h3><p>O painel atual mede apenas os eventos feitos neste navegador. Conecte analytics e backend antes de usar estes números para decisões comerciais.</p></section><section class="admin-panel"><span class="eyebrow">PRÓXIMO PASSO</span><h3>Da demo para operação.</h3><p>Conecte um backend para registrar sessões únicas, pagamento aprovado, estoque e eventos do provedor de checkout.</p></section></div>
      </section>

      <section v-else-if="tab === 'Cupons'" class="admin-view">
        <div class="admin-section-head"><div><p>Crie códigos de desconto para a loja. Eles funcionam na simulação de checkout deste navegador e mostram o uso no painel.</p></div></div>
        <div class="coupon-layout"><section class="admin-panel"><div class="admin-panel-title"><div><span class="eyebrow">NOVO CUPOM</span><h3>Uma razão a mais para ficar on.</h3></div></div><form class="coupon-form" @submit.prevent="saveCoupon"><label>Código<input v-model.trim="couponDraft.code" required maxlength="30" placeholder="EX.: ON10" /></label><label>Tipo<select v-model="couponDraft.type"><option value="percentage">Porcentagem</option><option value="fixed">Valor fixo (R$)</option><option value="shipping">Frete grátis</option></select></label><label v-if="couponDraft.type !== 'shipping'">{{ couponDraft.type === 'percentage' ? 'Desconto (%)' : 'Desconto (R$)' }}<input v-model.number="couponDraft.value" required min="1" :max="couponDraft.type === 'percentage' ? 100 : undefined" step="0.01" type="number" /></label><label>Pedido mínimo (R$)<input v-model.number="couponDraft.minimumOrder" min="0" step="0.01" type="number" /></label><label>Limite de usos <small>Vazio = ilimitado</small><input v-model.number="couponDraft.usageLimit" min="1" type="number" placeholder="Ilimitado" /></label><label class="admin-check"><input v-model="couponDraft.active" type="checkbox" />Ativar ao criar</label><button class="button button-primary full-width" type="submit"><Ticket :size="17" />Criar cupom</button></form></section><section class="admin-panel coupon-list"><div class="admin-panel-title"><div><span class="eyebrow">CUPONS ATIVOS E PAUSADOS</span><h3>{{ coupons.length }} código{{ coupons.length === 1 ? '' : 's' }}</h3></div></div><div v-if="coupons.length" class="coupon-cards"><article v-for="coupon in coupons" :key="coupon.id" :class="{ paused: !coupon.active }"><div><span class="coupon-code">{{ coupon.code }}</span><button title="Copiar código" @click="copyCoupon(coupon.code)"><Copy :size="14" /></button></div><strong>{{ coupon.type === 'percentage' ? `${coupon.value}% de desconto` : coupon.type === 'fixed' ? `${money(coupon.value)} de desconto` : 'Frete grátis' }}</strong><small>{{ coupon.minimumOrder ? `Pedidos a partir de ${money(coupon.minimumOrder)}` : 'Sem pedido mínimo' }} · {{ coupon.used }}{{ coupon.usageLimit ? ` / ${coupon.usageLimit}` : '' }} usos</small><footer><label class="coupon-active"><input v-model="coupon.active" type="checkbox" /><span>{{ coupon.active ? 'Ativo' : 'Pausado' }}</span></label><button class="icon-button danger" :aria-label="`Excluir cupom ${coupon.code}`" @click="deleteCoupon(coupon.id)"><Trash2 :size="16" /></button></footer></article></div><div v-else class="admin-empty"><Ticket :size="28" /><p>Nenhum cupom criado ainda.</p></div></section></div>
      </section>

      <section v-else class="admin-view">
        <div class="admin-section-head"><div><p>Pedidos de demonstração, dados de entrega e etiqueta pronta para imprimir. Nada é enviado aos Correios nesta versão local.</p></div><button class="button button-outline" :disabled="!orders.length" @click="downloadOrdersCsv"><Download :size="16" />Exportar CSV</button></div><div v-if="orders.length" class="orders-layout"><section class="admin-panel orders-table"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Status</th><th>Envio</th><th>Total</th></tr></thead><tbody><tr v-for="order in orders" :key="order.id" :class="{ selected: selectedOrder?.id === order.id }" @click="selectedOrderId = order.id"><td><strong>{{ order.id }}</strong><small>{{ new Date(order.createdAt).toLocaleDateString('pt-BR') }}</small></td><td>{{ order.customer.name }}<small>{{ order.customer.email }}</small></td><td><select :value="order.status" @click.stop @change="updateOrderStatus(order, ($event.target as HTMLSelectElement).value as Order['status'])"><option>Novo</option><option>Separando</option><option>Enviado</option><option>Entregue</option></select></td><td>{{ order.shipping }}</td><td>{{ money(order.total) }}</td></tr></tbody></table></section><aside v-if="selectedOrder" class="admin-panel shipping-detail"><div class="admin-panel-title"><div><span class="eyebrow">ETIQUETA DE ENVIO</span><h3>{{ selectedOrder.id }}</h3></div><button class="button button-outline print-hide" @click="printLabel"><Printer :size="16" />Imprimir</button></div><section id="shipping-label" class="shipping-label"><div class="shipping-label-head"><img src="/brand/assets/Logos/aegon-logo-positivo.svg" alt="aegon" /><strong>{{ selectedOrder.shipping }}</strong></div><div><small>DESTINATÁRIO</small><h4>{{ selectedOrder.customer.name }}</h4><p>{{ selectedOrder.customer.address.street }}, {{ selectedOrder.customer.address.number }}<br /><template v-if="selectedOrder.customer.address.complement">{{ selectedOrder.customer.address.complement }}<br /></template>{{ selectedOrder.customer.address.district }}<br />{{ selectedOrder.customer.address.city }}/{{ selectedOrder.customer.address.state }} · {{ selectedOrder.customer.address.cep }}</p></div><div class="shipping-label-bottom"><span>{{ selectedOrder.customer.phone }}</span><b>{{ selectedOrder.id }}</b></div></section><div class="shipping-items"><span>Itens no pedido</span><p v-for="item in selectedOrder.items" :key="`${item.productId}-${item.size}`">{{ item.quantity }}x {{ item.name }} <b>{{ item.size }}</b></p></div></aside></div><div v-else class="admin-panel admin-empty big"><ShoppingBag :size="38" /><h3>Seu primeiro pedido vai aparecer aqui.</h3><p>Faça uma simulação completa na loja para testar dados de envio, etiqueta e status.</p><RouterLink to="/" class="button button-primary">Abrir loja <ArrowUpRight :size="17" /></RouterLink></div>
      </section>
    </main>
  </div>
</template>
